INSERT INTO `landing_page_settings` VALUES
(1,'ERPGo SaaS','support@erpgosaas.com','+1 (555) 123-4567','123 Business Ave, City, State 12345','{\"sections\": {\"hero\": {\"variant\": \"hero1\", \"title\": \"The Complete Cloud ERP Platform for Modern Enterprises\", \"subtitle\": \"Streamline your entire business lifecycle, from finance to operations, with ERPGo SaaS. One platform, infinite possibilities.\", \"primary_button_text\": \"Start Free Trial\", \"primary_button_link\": \"http:\\/\\/localhost\\/register\", \"secondary_button_text\": \"Login\", \"secondary_button_link\": \"http:\\/\\/localhost\\/login\", \"highlight_text\": \"ERPGo SaaS\", \"image\": \"packages\\/workdo\\/LandingPage\\/src\\/Resources\\/assets\\/img\\/hero.png\"}, \"header\": {\"variant\": \"header1\", \"company_name\": \"ERPGo SaaS\", \"cta_text\": \"Get Started\", \"enable_pricing_link\": true, \"navigation_items\": [{\"text\": \"Home\", \"href\": \"http:\\/\\/localhost\"}]}, \"stats\": {\"variant\": \"stats1\", \"stats\": [{\"label\": \"Businesses Trust Us\", \"value\": \"20,000+\"}, {\"label\": \"Uptime Guarantee\", \"value\": \"99.9%\"}, {\"label\": \"Customer Support\", \"value\": \"24\\/7\"}, {\"label\": \"Countries Worldwide\", \"value\": \"70+\"}]}, \"features\": {\"variant\": \"features1\", \"title\": \"Powerful Features\", \"subtitle\": \"Everything your business needs in one integrated platform\", \"features\": [{\"title\": \"ERP System\", \"description\": \"Streamline resources and operations with comprehensive enterprise resource planning.\", \"icon\": \"Building2\"}, {\"title\": \"Accounting System\", \"description\": \"Manage finances with ease and accuracy through automated accounting tools.\", \"icon\": \"Calculator\"}, {\"title\": \"CRM System\", \"description\": \"Strengthen customer relationships and improve sales with powerful CRM tools.\", \"icon\": \"Users\"}, {\"title\": \"POS System\", \"description\": \"Fast and reliable point-of-sale solution for retail and service businesses.\", \"icon\": \"CreditCard\"}, {\"title\": \"HRM System\", \"description\": \"Simplify employee management and payroll with integrated HR tools.\", \"icon\": \"UserCheck\"}, {\"title\": \"Project System\", \"description\": \"Organize and track projects efficiently with comprehensive project management.\", \"icon\": \"FolderOpen\"}]}, \"modules\": {\"variant\": \"modules1\", \"title\": \"Complete Business Solutions\", \"subtitle\": \"Discover our comprehensive modules designed to streamline every aspect of your business operations\", \"modules\": [{\"key\": \"hrm\", \"label\": \"Human Resources\", \"title\": \"HRM System\", \"description\": \"Transform your human resource operations with a comprehensive suite for the entire employee lifecycle. Efficiently manage recruitment, onboarding, attendance, and payroll processing while ensuring compliance. foster a positive workplace culture with performance tracking and self-service portals that empower your workforce to thrive.\", \"image\": \"packages\\/workdo\\/LandingPage\\/src\\/Resources\\/assets\\/img\\/hrm.png\"}, {\"key\": \"account\", \"label\": \"Accounting & Finance\", \"title\": \"Accounting System\", \"description\": \"Take command of your financial data with an advanced double-entry accounting system designed for accuracy and speed. Automate complex billing cycles, reconcile bank transactions in seconds, and generate insightful financial reports that give you a clear picture of your profitability. Securely manage assets, liabilities, and equity with enterprise-grade precision.\", \"image\": \"packages\\/workdo\\/LandingPage\\/src\\/Resources\\/assets\\/img\\/accounting.png\"}, {\"key\": \"taskly\", \"label\": \"Project Management\", \"title\": \"Task & Project System\", \"description\": \"Deliver projects on time and within budget using our robust project management tools. Visualize workflows with interactive Kanban boards and Gantt charts, enabling seamless collaboration among teams. Track milestones, allocate resources effectively, and monitor productivity in real-time to ensure every project is a success story.\", \"image\": \"packages\\/workdo\\/LandingPage\\/src\\/Resources\\/assets\\/img\\/project.png\"}, {\"key\": \"crm\", \"label\": \"CRM & Sales\", \"title\": \"CRM System\", \"description\": \"Supercharge your sales engine with a customer relationship management (CRM) system that turns leads into loyal clients. Track every interaction, manage sales pipelines with drag-and-drop ease, and automate follow-ups to never miss an opportunity. Analyze customer behavior to tailor your strategies and close deals faster than ever before.\", \"image\": \"packages\\/workdo\\/LandingPage\\/src\\/Resources\\/assets\\/img\\/crm.png\"}, {\"key\": \"pos\", \"label\": \"Point of Sale\", \"title\": \"POS System\", \"description\": \"Revolutionize your retail operations with a lightning-fast Point of Sale (POS) system that keeps your business moving. synchronize inventory across multiple warehouses in real-time, process transactions securely, and manage customer loyalty programs effortlessly. From the checkout counter to the back office, ensure smooth, error-free operations.\", \"image\": \"packages\\/workdo\\/LandingPage\\/src\\/Resources\\/assets\\/img\\/pos.png\"}]}, \"benefits\": {\"variant\": \"benefits1\", \"title\": \"Why Choose ERPGo SaaS?\", \"benefits\": [{\"title\": \"Unified Business Ecosystem\", \"description\": \"Breakdown silos between your business functions. Our integrated modules for HRM, Accounting, CRM, Projects, and POS work in perfect harmony to provide a unified data source for your entire enterprise.\"}, {\"title\": \"Strategic Human Resource Management\", \"description\": \"Transform your workforce management. Efficiently handle recruitment, onboarding, and attendance while ensuring compliant payroll processing. Empower your team with self-service portals and performance tracking.\"}, {\"title\": \"Professional Financial Precision\", \"description\": \"Ensure absolute accuracy with our robust accounting system. Automate billing cycles, reconcile bank transactions, and manage assets with enterprise-grade precision, providing a crystal-clear view of your financial health.\"}, {\"title\": \"Dynamic Project & Task Mastery\", \"description\": \"Deliver projects on time and within budget. Visualize complex workflows with Kanban boards and Gantt charts, enabling seamless collaboration. Track milestones and allocate resources effectively for maximum productivity.\"}, {\"title\": \"Integrated Sales & CRM Growth Engine\", \"description\": \"Supercharge your revenue streams. Track every customer interaction, manage sales pipelines with ease, and streamline retail operations with our lightning-fast POS system to close deals faster.\"}, {\"title\": \"Comprehensive Reporting & Analytics\", \"description\": \"Make informed decisions with real-time insights at your fingertips. Generate detailed reports across finance, sales, and operations. Visualize performance trends through intuitive charts to drive strategic growth.\"}]}, \"gallery\": {\"variant\": \"gallery1\", \"title\": \"Gallery\", \"subtitle\": \"Explore our product in action\", \"images\": [\"packages\\/workdo\\/LandingPage\\/src\\/Resources\\/assets\\/img\\/gallery1.jpeg\", \"packages\\/workdo\\/LandingPage\\/src\\/Resources\\/assets\\/img\\/gallery2.jpeg\", \"packages\\/workdo\\/LandingPage\\/src\\/Resources\\/assets\\/img\\/gallery3.jpeg\", \"packages\\/workdo\\/LandingPage\\/src\\/Resources\\/assets\\/img\\/gallery4.jpeg\", \"packages\\/workdo\\/LandingPage\\/src\\/Resources\\/assets\\/img\\/gallery5.jpeg\", \"packages\\/workdo\\/LandingPage\\/src\\/Resources\\/assets\\/img\\/gallery6.jpeg\", \"packages\\/workdo\\/LandingPage\\/src\\/Resources\\/assets\\/img\\/gallery7.jpeg\"]}, \"cta\": {\"variant\": \"cta1\", \"title\": \"Ready to Transform Your Business?\", \"subtitle\": \"Join thousands of businesses already using ERPGo SaaS to streamline their operations.\", \"primary_button\": \"Start Free Trial\", \"secondary_button\": \"Contact Sales\"}, \"pricing\": {\"title\": \"Flexible Pricing Plans\", \"subtitle\": \"Choose the perfect subscription plan for your business needs\", \"default_subscription_type\": \"pre-package\", \"default_price_type\": \"monthly\", \"show_pre_package\": true, \"show_monthly_yearly_toggle\": true, \"empty_message\": \"No plans available. Check back later for new pricing plans.\"}, \"footer\": {\"variant\": \"footer1\", \"description\": \"The complete business management solution for modern enterprises.\", \"email\": \"support@erpgosaas.com\", \"phone\": \"+1 (555) 123-4567\", \"newsletter_title\": \"Join Our Community\", \"newsletter_description\": \"Subscribe to our newsletter for the latest business insights and updates.\", \"newsletter_button_text\": \"Subscribe\", \"copyright_text\": \"Copyright © Vetralis\", \"navigation_sections\": [{\"title\": \"Product\", \"links\": [{\"text\": \"Features\", \"href\": \"#features\"}, {\"text\": \"Pricing\", \"href\": \"#pricing\"}, {\"text\": \"Demo\", \"href\": \"#demo\"}]}, {\"title\": \"Company\", \"links\": [{\"text\": \"About\", \"href\": \"#about\"}, {\"text\": \"Contact\", \"href\": \"#contact\"}, {\"text\": \"Support\", \"href\": \"#support\"}]}]}}, \"section_visibility\": {\"header\": true, \"hero\": true, \"stats\": true, \"features\": true, \"modules\": true, \"benefits\": true, \"gallery\": true, \"cta\": true, \"footer\": true, \"pricing\": false}, \"section_order\": [\"header\", \"hero\", \"stats\", \"features\", \"modules\", \"benefits\", \"gallery\", \"cta\", \"footer\"], \"colors\": {\"primary\": \"#10b77f\", \"secondary\": \"#059669\", \"accent\": \"#065f46\"}}','2026-06-09 04:29:34','2026-06-12 01:43:36');
