CREATE TABLE `marketplace_settings` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL DEFAULT 'Marketplace',
  `subtitle` text DEFAULT NULL,
