(1,'Pos Module Marketplace','Comprehensive pos tools for your applications','Pos','{\"sections\":{\"hero\":{\"variant\":\"hero1\",\"title\":\"Pos Module for ERPGo SaaS\",\"subtitle\":\"Streamline your pos workflow with comprehensive tools and automated management.\",\"primary_button_text\":\"Install Pos Module\",\"primary_button_link\":\"#install\",\"secondary_button_text\":\"Learn More\",\"secondary_button_link\":\"#learn\",\"image\":\"\"},\"modules\":{\"variant\":\"modules1\",\"title\":\"Pos Module\",\"subtitle\":\"Enhance your workflow with powerful pos tools\"},\"dedication\":{\"variant\":\"dedication1\",\"title\":\"Dedicated Pos Features\",\"description\":\"Our pos module provides comprehensive capabilities for modern workflows.\",\"subSections\":[{\"title\":\"Feature 1\",\"description\":\"Description of first key feature for pos management.\",\"keyPoints\":[\"Point 1\",\"Point 2\",\"Point 3\",\"Point 4\"],\"screenshot\":\"\\/packages\\/workdo\\/Pos\\/src\\/marketplace\\/image1.png\"},{\"title\":\"Feature 2\",\"description\":\"Description of second key feature for pos organization.\",\"keyPoints\":[\"Point 1\",\"Point 2\",\"Point 3\",\"Point 4\"],\"screenshot\":\"\\/packages\\/workdo\\/Pos\\/src\\/marketplace\\/image2.png\"},{\"title\":\"Feature 3\",\"description\":\"Description of third key feature for pos tracking.\",\"keyPoints\":[\"Point 1\",\"Point 2\",\"Point 3\",\"Point 4\"],\"screenshot\":\"\\/packages\\/workdo\\/Pos\\/src\\/marketplace\\/image3.png\"}]},\"screenshots\":{\"variant\":\"screenshots1\",\"title\":\"Pos Module in Action\",\"subtitle\":\"See how our pos tools improve your workflow\",\"images\":[]},\"why_choose\":{\"variant\":\"whychoose1\",\"title\":\"Why Choose Pos Module?\",\"subtitle\":\"Improve efficiency with comprehensive pos management\",\"benefits\":[{\"title\":\"Automated Process\",\"description\":\"Automate your pos workflow to save time and reduce errors.\",\"icon\":\"Play\",\"color\":\"blue\"},{\"title\":\"Comprehensive Reports\",\"description\":\"Get detailed reports with metrics and performance data.\",\"icon\":\"FileText\",\"color\":\"green\"},{\"title\":\"Team Collaboration\",\"description\":\"Share results and collaborate effectively with your team.\",\"icon\":\"Users\",\"color\":\"purple\"},{\"title\":\"Easy Integration\",\"description\":\"Seamlessly integrate with your existing workflow.\",\"icon\":\"GitBranch\",\"color\":\"red\"},{\"title\":\"Quality Management\",\"description\":\"Maintain high quality with comprehensive management tools.\",\"icon\":\"CheckCircle\",\"color\":\"yellow\"},{\"title\":\"Performance Tracking\",\"description\":\"Track performance and identify improvements early.\",\"icon\":\"Activity\",\"color\":\"indigo\"}]}},\"section_visibility\":{\"header\":true,\"hero\":true,\"modules\":true,\"dedication\":true,\"screenshots\":true,\"why_choose\":true,\"cta\":true,\"footer\":true},\"section_order\":[\"header\",\"hero\",\"modules\",\"dedication\",\"screenshots\",\"why_choose\",\"cta\",\"footer\"]}','2026-06-09 04:23:30','2026-06-09 04:23:30'),
(2,'AI Assistant Content Generator','Intelligent content generation integrated across all platform modules','AIAssistant','{\"sections\":{\"hero\":{\"variant\":\"hero1\",\"title\":\"AI Assistant for ERPGo SaaS\",\"subtitle\":\"Transform content creation across your entire platform with intelligent AI-powered generation integrated seamlessly into every form and module.\",\"primary_button_text\":\"Install AI Assistant Module\",\"primary_button_link\":\"#install\",\"secondary_button_text\":\"Learn More\",\"secondary_button_link\":\"#learn\",\"image\":\"\"},\"modules\":{\"variant\":\"modules1\",\"title\":\"AI Assistant Module\",\"subtitle\":\"Revolutionize content creation with intelligent AI integration across all platform modules\"},\"dedication\":{\"variant\":\"dedication1\",\"title\":\"Dedicated AI Assistant Features\",\"description\":\"Our AI Assistant module provides intelligent content generation capabilities integrated across 16+ modules with multi-provider AI support and advanced customization options.\",\"subSections\":[{\"title\":\"Universal AI Integration\",\"description\":\"Seamlessly integrated AI content generation across 16+ modules including HRM, Sales, CRM, Support, and more with contextual intelligence for relevant content creation.\",\"keyPoints\":[\"Integration across 16+ platform modules\",\"Contextual AI understanding for each module\",\"One-click content generation in any form\",\"Seamless workflow integration without disruption\"],\"screenshot\":\"\\/packages\\/workdo\\/AIAssistant\\/src\\/marketplace\\/image1.png\"},{\"title\":\"Multi-Provider AI Support\",\"description\":\"Advanced AI capabilities with support for multiple providers including OpenAI, Claude, Gemini, and Anthropic with dynamic model selection and secure API management.\",\"keyPoints\":[\"Multiple AI provider support (OpenAI, Claude, Gemini)\",\"Dynamic model selection based on provider\",\"Secure API key management with encryption\",\"Company-side configuration and control\"],\